tool_and_message_events.command:
/bin/bash -lc 'set -euo pipefail
catalog_copy=$(mktemp ./.catalog-review.XXXXXX)
trap '"'rm -- \""'$catalog_copy"'"' EXIT
cp fixture/catalog.json \""'$catalog_copy"
printf '"'Before pin: '
node desk.mjs \""'$catalog_copy" pins
printf '"'Pin response: '
node desk.mjs \""'$catalog_copy" pin a
printf '"'Saved file:\\n'
cat \""'$catalog_copy"
printf '"'\\nAfter reopening: '
node desk.mjs \""'$catalog_copy" pins
node --input-type=module - "$catalog_copy" "$(node desk.mjs "$catalog_copy" pins)" <<'"'JS'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
const [file, output] = process.argv.slice(2);
assert.deepEqual(JSON.parse(output), ['Alpha', 'Beta']);
assert.equal(JSON.parse(readFileSync(file, 'utf8')).find(card => card.id === 'a').pinned, true);
assert.equal(JSON.parse(readFileSync('fixture/catalog.json', 'utf8')).find(card => card.id === 'a').pinned, false);
JS"
